def f(x):
    return x**3 - x - 2

a, b = 1.0, 2.0
tol = 1e-6
while (b - a) / 2 > tol:
    c = (a + b) / 2
    if f(a) * f(c) < 0:
        b = c
    else:
        a = c
print(f"{(a+b)/2:.4f}")

def lagrange(xs, ys, x):
    total = 0.0
    n = len(xs)
    for i in range(n):
        L = 1.0
        for j in range(n):
            if j != i:
                L *= (x - xs[j]) / (xs[i] - xs[j])
        total += ys[i] * L
    return total

print(f"{lagrange([1, 3, 4], [2, 4, 7], 2):.4f}")

